import { Badge, Sheet, SheetDescription, SheetHeader, SheetTitle, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@clossys/designer-ui';

/** One step as graph.json records it: what runs, what it reads and writes, and who holds its seat. */
export interface PipelineStep {
  id: string;
  label: string;
  lane: string;
  command: string;
  inputs: readonly string[];
  outputs: readonly string[];
  options: readonly string[];
  /** The seat holder's label, or null for an open seat. */
  seat: string | null;
  status: string;
}

/** Writer copy of the step sheet (studio.pipeline.step.*, studio.pipeline.seat.*, studio.pipeline.empty.*). */
export interface StepSheetCopy {
  field: string;
  value: string;
  command: string;
  inputs: string;
  outputs: string;
  options: string;
  seat: string;
  status: string;
  none: string;
  openSeat: string;
  emptyTitle: string;
  emptyDescription: string;
}

/** The `sheet` input of `sections.producer.step-sheet`: the selected step, or null, and whether the sheet is open. */
export interface StepSheetInput { open: boolean; step: PipelineStep | null; copy: StepSheetCopy }

const list = (values: readonly string[], none: string) => values.length ? values.join(', ') : none;

/** `sections.producer.step-sheet`: the selected step's facts in a stock shadcn Sheet; an open seat and no selection are stated, never blank. */
export default function StepSheetSection({ sheet, onOpenChange, ...provenance }: { sheet: StepSheetInput; onOpenChange?: (open: boolean) => void } & { [marker: `data-clossys-${string}`]: string }) {
  const { step, copy } = sheet;
  return <Sheet {...provenance} isOpen={sheet.open} onOpenChange={onOpenChange} isDismissable>
    {step ? <>
      <SheetHeader>
        <SheetTitle>{step.label}</SheetTitle>
        <SheetDescription>{step.lane}</SheetDescription>
      </SheetHeader>
      <Table aria-label={step.label}>
        <TableHeader>
          <TableHead isRowHeader>{copy.field}</TableHead>
          <TableHead>{copy.value}</TableHead>
        </TableHeader>
        <TableBody>
          <TableRow id="command"><TableCell>{copy.command}</TableCell><TableCell><code>{step.command}</code></TableCell></TableRow>
          <TableRow id="inputs"><TableCell>{copy.inputs}</TableCell><TableCell>{list(step.inputs, copy.none)}</TableCell></TableRow>
          <TableRow id="outputs"><TableCell>{copy.outputs}</TableCell><TableCell>{list(step.outputs, copy.none)}</TableCell></TableRow>
          <TableRow id="options"><TableCell>{copy.options}</TableCell><TableCell>{list(step.options, copy.none)}</TableCell></TableRow>
          <TableRow id="seat"><TableCell>{copy.seat}</TableCell><TableCell>{step.seat ?? <Badge variant="outline">{copy.openSeat}</Badge>}</TableCell></TableRow>
          <TableRow id="status"><TableCell>{copy.status}</TableCell><TableCell><Badge variant="secondary">{step.status}</Badge></TableCell></TableRow>
        </TableBody>
      </Table>
    </> : <SheetHeader>
      <SheetTitle>{copy.emptyTitle}</SheetTitle>
      <SheetDescription>{copy.emptyDescription}</SheetDescription>
    </SheetHeader>}
  </Sheet>;
}
